#!/usr/bin/env python3\n\"\"\"\nAuto Video Editor - Practical MVP for vloggers\nSimple, working solution: removes silence, detects pauses, exports MP4\n\"\"\"\n\nimport argparse\nimport sys\nimport os\nimport json\nfrom pathlib import Path\nfrom typing import List, Tuple\n\ntry:\n    import numpy as np\n    import librosa\n    import soundfile as sf\nexcept ImportError:\n    print(\"Installing required packages...\")\n    os.system(\"pip install numpy librosa soundfile\")\n    import numpy as np\n    import librosa\n    import soundfile as sf\n\nimport subprocess\nfrom datetime import datetime\n\n\nclass SimpleVideoEditor:\n    \"\"\"Minimal, practical video editor for vloggers\"\"\"\n    \n    def __init__(self, input_path, output_path=\"output.mp4\", silence_threshold=-40, \n                 min_silence_duration=1.0, quality=720):\n        self.input_path = input_path\n        self.output_path = output_path\n        self.silence_threshold = silence_threshold  # dB\n        self.min_silence_duration = min_silence_duration  # seconds\n        self.quality = quality\n        self.temp_audio = \"_temp_audio.wav\"\n        self.temp_video = \"_temp_video.mp4\"\n        \n        print(f\"📁 Input: {input_path}\")\n        print(f\"💾 Output: {output_path}\")\n        print(f\"🔊 Silence threshold: {silence_threshold} dB\")\n        print(f\"⏱️  Min silence duration: {min_silence_duration}s\")\n    \n    def extract_audio(self):\n        \"\"\"Extract audio from video using FFmpeg\"\"\"\n        print(\"\\n🎵 Extracting audio...\")\n        cmd = [\n            \"ffmpeg\", \"-i\", self.input_path,\n            \"-q:a\", \"9\",  # Highest quality\n            \"-n\",  # Never overwrite\n            self.temp_audio\n        ]\n        subprocess.run(cmd, capture_output=True, check=True)\n        print(f\"✅ Audio extracted\")\n    \n    def detect_silence(self) -> List[Tuple[float, float]]:\n        \"\"\"Detect silent segments in audio\n        \n        Returns:\n            List of (start_time, end_time) tuples for silent segments\n        \"\"\"\n        print(\"\\n🔍 Detecting silence...\")\n        \n        # Load audio\n        y, sr = librosa.load(self.temp_audio, sr=None)\n        \n        # Convert to dB\n        S = librosa.feature.melspectrogram(y=y, sr=sr)\n        S_db = librosa.power_to_db(S, ref=np.max)\n        \n        # Get RMS energy per frame\n        rms = librosa.feature.rms(y=y)[0]\n        rms_db = librosa.power_to_db(rms)\n        \n        # Frames per second\n        frames_per_sec = sr / 512  # 512 is default hop_length\n        \n        # Find silent frames (below threshold)\n        silent_frames = rms_db < self.silence_threshold\n        \n        # Convert to time\n        frame_times = librosa.frames_to_time(np.arange(len(rms_db)), sr=sr, hop_length=512)\n        \n        # Group consecutive silent frames\n        silent_segments = []\n        in_silence = False\n        silence_start = 0\n        \n        for i, is_silent in enumerate(silent_frames):\n            if is_silent and not in_silence:\n                # Start of silence\n                silence_start = frame_times[i]\n                in_silence = True\n            elif not is_silent and in_silence:\n                # End of silence\n                silence_end = frame_times[i]\n                duration = silence_end - silence_start\n                \n                if duration >= self.min_silence_duration:\n                    silent_segments.append((silence_start, silence_end))\n                \n                in_silence = False\n        \n        # Handle silence at end\n        if in_silence:\n            silence_end = frame_times[-1]\n            duration = silence_end - silence_start\n            if duration >= self.min_silence_duration:\n                silent_segments.append((silence_start, silence_end))\n        \n        total_silence = sum(end - start for start, end in silent_segments)\n        print(f\"✅ Found {len(silent_segments)} silent segments ({total_silence:.1f}s total)\")\n        \n        for i, (start, end) in enumerate(silent_segments[:5], 1):\n            print(f\"   Segment {i}: {start:.1f}s - {end:.1f}s ({end-start:.1f}s)\")\n        if len(silent_segments) > 5:\n            print(f\"   ... and {len(silent_segments) - 5} more\")\n        \n        return silent_segments\n    \n    def get_video_duration(self) -> float:\n        \"\"\"Get video duration using ffprobe\"\"\"\n        cmd = [\n            \"ffprobe\", \"-v\", \"error\",\n            \"-show_entries\", \"format=duration\",\n            \"-of\", \"default=noprint_wrappers=1:nokey=1:noprint_wrappers=1\",\n            self.input_path\n        ]\n        result = subprocess.run(cmd, capture_output=True, text=True, check=True)\n        return float(result.stdout.strip())\n    \n    def segments_to_keep(self, silent_segments: List[Tuple[float, float]], \n                         duration: float) -> List[Tuple[float, float]]:\n        \"\"\"Convert silent segments to segments we want to keep\n        \n        Args:\n            silent_segments: List of (start, end) times to remove\n            duration: Total video duration\n            \n        Returns:\n            List of (start, end) times to keep\n        \"\"\"\n        if not silent_segments:\n            return [(0, duration)]\n        \n        # Sort and merge overlapping silences\n        sorted_silences = sorted(silent_segments)\n        merged = []\n        \n        for start, end in sorted_silences:\n            if merged and start <= merged[-1][1]:\n                merged[-1] = (merged[-1][0], max(merged[-1][1], end))\n            else:\n                merged.append((start, end))\n        \n        # Find keep segments\n        keep = []\n        current_pos = 0.0\n        \n        for start, end in merged:\n            if start > current_pos:\n                keep.append((current_pos, start))\n            current_pos = end\n        \n        if current_pos < duration:\n            keep.append((current_pos, duration))\n        \n        return keep\n    \n    def create_ffmpeg_filter(self, keep_segments: List[Tuple[float, float]]) -> str:\n        \"\"\"Create FFmpeg filter string for video concatenation\n        \n        Args:\n            keep_segments: List of (start, end) times to keep\n            \n        Returns:\n            FFmpeg filter complex string\n        \"\"\"\n        filters = []\n        \n        # Create trim filters for each segment\n        for i, (start, end) in enumerate(keep_segments):\n            filters.append(f\"[0:v]trim=start={start}:end={end},setpts=PTS-STARTPTS[v{i}]\")\n            filters.append(f\"[0:a]atrim=start={start}:end={end},asetpts=PTS-STARTPTS[a{i}]\")\n        \n        # Concatenate all segments\n        n = len(keep_segments)\n        v_inputs = \"\".join([f\"[v{i}]\" for i in range(n)])\n        a_inputs = \"\".join([f\"[a{i}]\" for i in range(n)])\n        \n        filters.append(f\"{v_inputs}concat=n={n}:v=1:a=0[v_out]\")\n        filters.append(f\"{a_inputs}concat=n={n}:v=0:a=1[a_out]\")\n        \n        return \";\".join(filters)\n    \n    def create_edited_video(self, keep_segments: List[Tuple[float, float]]):\n        \"\"\"Create edited video using FFmpeg\n        \n        Args:\n            keep_segments: List of (start, end) times to keep\n        \"\"\"\n        print(\"\\n🎬 Creating edited video...\")\n        \n        filter_complex = self.create_ffmpeg_filter(keep_segments)\n        \n        # Quality settings\n        if self.quality == 1080:\n            scale_filter = \"scale=1920:1080\"\n        else:  # 720\n            scale_filter = \"scale=1280:720\"\n        \n        cmd = [\n            \"ffmpeg\",\n            \"-i\", self.input_path,\n            \"-filter_complex\", filter_complex,\n            \"-map\", \"[v_out]\",\n            \"-map\", \"[a_out]\",\n            \"-c:v\", \"libx264\",\n            \"-preset\", \"medium\",  # faster encoding\n            \"-crf\", \"23\",  # quality (lower = better, 0-51)\n            \"-c:a\", \"aac\",\n            \"-b:a\", \"128k\",\n            \"-y\",  # overwrite\n            self.output_path\n        ]\n        \n        print(f\"   FFmpeg is encoding... (this may take a while)\")\n        result = subprocess.run(cmd, capture_output=True, text=True)\n        \n        if result.returncode != 0:\n            print(f\"❌ FFmpeg error: {result.stderr}\")\n            raise Exception(f\"FFmpeg encoding failed\")\n        \n        print(f\"✅ Edited video created\")\n    \n    def get_output_stats(self) -> dict:\n        \"\"\"Get statistics about the edited video\"\"\"\n        cmd = [\n            \"ffprobe\", \"-v\", \"error\",\n            \"-show_entries\", \"format=duration\",\n            \"-of\", \"default=noprint_wrappers=1:nokey=1\",\n            self.output_path\n        ]\n        result = subprocess.run(cmd, capture_output=True, text=True, check=True)\n        output_duration = float(result.stdout.strip())\n        \n        return {\"duration\": output_duration}\n    \n    def cleanup(self):\n        \"\"\"Remove temporary files\"\"\"\n        for temp_file in [self.temp_audio, self.temp_video]:\n            if Path(temp_file).exists():\n                Path(temp_file).unlink()\n    \n    def save_report(self, original_duration, edited_duration, silent_segments, keep_segments):\n        \"\"\"Save a JSON report of the editing\"\"\"\n        output_dir = Path(self.output_path).parent or Path(\".\")\n        report_path = output_dir / \"editing_report.json\"\n        \n        report = {\n            \"timestamp\": datetime.now().isoformat(),\n            \"input_file\": str(self.input_path),\n            \"output_file\": str(self.output_path),\n            \"original_duration_seconds\": original_duration,\n            \"edited_duration_seconds\": edited_duration,\n            \"reduction_seconds\": original_duration - edited_duration,\n            \"reduction_percentage\": (1 - edited_duration / original_duration) * 100 if original_duration > 0 else 0,\n            \"silent_segments_removed\": len(silent_segments),\n            \"total_silence_removed_seconds\": sum(end - start for start, end in silent_segments),\n            \"segments_kept\": [\n                {\"start\": round(start, 2), \"end\": round(end, 2), \"duration\": round(end - start, 2)}\n                for start, end in keep_segments\n            ]\n        }\n        \n        with open(report_path, 'w', encoding='utf-8') as f:\n            json.dump(report, f, indent=2, ensure_ascii=False)\n        \n        print(f\"\\n📋 Report saved to: {report_path}\")\n    \n    def process(self):\n        \"\"\"Main processing pipeline\"\"\"\n        try:\n            # Get original duration\n            print(\"\\n📊 Analyzing video...\")\n            original_duration = self.get_video_duration()\n            print(f\"✅ Original duration: {original_duration:.1f}s ({int(original_duration//60)}m {int(original_duration%60)}s)\")\n            \n            # Extract audio\n            self.extract_audio()\n            \n            # Detect silence\n            silent_segments = self.detect_silence()\n            \n            # Calculate segments to keep\n            keep_segments = self.segments_to_keep(silent_segments, original_duration)\n            \n            print(f\"\\n✅ Will keep {len(keep_segments)} segments\")\n            total_keep_time = sum(end - start for start, end in keep_segments)\n            print(f\"   Total keep time: {total_keep_time:.1f}s\")\n            \n            # Create edited video\n            self.create_edited_video(keep_segments)\n            \n            # Get output stats\n            output_stats = self.get_output_stats()\n            edited_duration = output_stats['duration']\n            \n            # Save report\n            self.save_report(original_duration, edited_duration, silent_segments, keep_segments)\n            \n            # Print summary\n            print(f\"\\n\" + \"=\"*50)\n            print(f\"✅ DONE!\")\n            print(f\"=\"*50)\n            print(f\"📊 Summary:\")\n            print(f\"   Original:  {original_duration:.1f}s ({int(original_duration//60)}m {int(original_duration%60)}s)\")\n            print(f\"   Edited:    {edited_duration:.1f}s ({int(edited_duration//60)}m {int(edited_duration%60)}s)\")\n            print(f\"   Removed:   {original_duration - edited_duration:.1f}s\")\n            print(f\"   Reduction: {(1 - edited_duration/original_duration)*100:.1f}%\")\n            print(f\"\\n   Output: {self.output_path}\")\n            print(f\"=\"*50)\n            \n        finally:\n            self.cleanup()\n\n\ndef main():\n    parser = argparse.ArgumentParser(\n        description=\"Auto Video Editor - Remove silence from your vlogs\",\n        formatter_class=argparse.RawDescriptionHelpFormatter,\n        epilog=\"\"\"\nExamples:\n  # Basic - remove silence longer than 1 second\n  python main.py --input raw_video.mp4 --output edited.mp4\n  \n  # Aggressive - remove silence longer than 0.5 seconds\n  python main.py --input raw_video.mp4 --output edited.mp4 --min-silence 0.5\n  \n  # High quality output\n  python main.py --input raw_video.mp4 --output edited.mp4 --quality 1080\n  \n  # Custom silence threshold\n  python main.py --input raw_video.mp4 --output edited.mp4 --threshold -35\n        \"\"\"\n    )\n    \n    parser.add_argument(\n        \"--input\", \"-i\",\n        type=str,\n        required=True,\n        help=\"Input video file path (required)\"\n    )\n    \n    parser.add_argument(\n        \"--output\", \"-o\",\n        type=str,\n        default=\"output.mp4\",\n        help=\"Output video file path (default: output.mp4)\"\n    )\n    \n    parser.add_argument(\n        \"--min-silence\",\n        type=float,\n        default=1.0,\n        help=\"Minimum silence duration to remove in seconds (default: 1.0)\"\n    )\n    \n    parser.add_argument(\n        \"--threshold\",\n        type=float,\n        default=-40,\n        help=\"Silence detection threshold in dB (default: -40, lower = more aggressive)\"\n    )\n    \n    parser.add_argument(\n        \"--quality\", \"-q\",\n        type=int,\n        choices=[720, 1080],\n        default=720,\n        help=\"Output video quality (default: 720)\"\n    )\n    \n    args = parser.parse_args()\n    \n    # Validate input\n    if not Path(args.input).exists():\n        print(f\"❌ Error: Input file not found: {args.input}\")\n        sys.exit(1)\n    \n    # Run editor\n    print(f\"\\n🎬 Auto Video Editor\")\n    print(f\"{'='*50}\")\n    \n    editor = SimpleVideoEditor(\n        input_path=args.input,\n        output_path=args.output,\n        silence_threshold=args.threshold,\n        min_silence_duration=args.min_silence,\n        quality=args.quality\n    )\n    \n    editor.process()\n\n\nif __name__ == \"__main__\":\n    main()\n"
